    const group=bookingCalendarLabel(o),dateOk=f.date==='All dates'||f.date==='Last 7 days'||f.date===group||f.date===group.split(' · ').pop();
    const searchOk=!q||`${o.id} ${o.guest} ${o.room} ${o.item} ${o.hotel}`.toLowerCase().includes(q);
